166	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
167	        // Idempotent create: if this request repeats an already-seen 'Idempotency-Key', return the
168	        // owner created the first time (200) rather than creating a duplicate.
169	        String idempotencyKey = idempotencyKey();
170	        if (idempotencyKey != null) {
171	            Integer existingId = idempotentCreates.get(idempotencyKey);
172	            if (existingId != null) {
173	                Owner existing = this.clinicService.findOwnerById(existingId);
174	                if (existing != null) {
175	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
176	                }
177	            }
178	        }
179	        List<String> missingFields = new ArrayList<>();
180	        if (isBlank(ownerFieldsDto.getFirstName())) {
181	            missingFields.add("firstName");
182	        }
183	        if (isBlank(ownerFieldsDto.getLastName())) {
184	            missingFields.add("lastName");
185	        }
186	        // Normalize whichever address form was supplied and fold it into the DTO: the structured
187	        // 'addressLine1'/'addressLine2' win when a non-blank 'addressLine1' is present, otherwise the
188	        // flat 'address' is used. The composed value is stored back into 'address' so every reader of
189	        // the owner's address sees the effective (structured-or-flat) value.
190	        applyAddress(ownerFieldsDto);
191	        if (isBlank(ownerFieldsDto.getAddress())) {
192	            missingFields.add("address");
193	        }
194	        if (isBlank(ownerFieldsDto.getCity())) {
195	            missingFields.add("city");
196	        }
197	        if (isBlank(ownerFieldsDto.getTelephone())) {
198	            missingFields.add("telephone");
199	        }
200	        if (!missingFields.isEmpty()) {
201	            throw new MissingOwnerFieldsException(missingFields);
202	        }
203	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
204	        LocalDate suppliedRegistrationDate = ownerFieldsDto.getRegistrationDate();
205	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
206	            throw new FutureRegistrationDateException(
207	                "registrationDate must not be later than the server date");
208	        }
209	        LocalDate registrationDate = toBusinessDay(
210	            suppliedRegistrationDate != null
211	                ? suppliedRegistrationDate
212	                : LocalDate.now());
213	        long registeredOnDay = this.clinicService.findAllOwners().stream()
214	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
215	            .count();
216	        if (registeredOnDay >= 100) {
217	            throw new DailyRegistrationLimitException(
218	                "100 or more owners have already been registered today");
219	        }
220	        boolean bulkSignupWarning = registeredOnDay > 80;
221	        String city = ownerFieldsDto.getCity();
222	        long ownersInCity = this.clinicService.findAllOwners().stream()
223	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
224	            .count();
225	        if (ownersInCity >= 50) {
226	            throw new CityAtCapacityException(
227	                "the owner's city already contains 50 or more owners");
228	        }
229	        String telephone = toE164(ownerFieldsDto.getTelephone());
230	        ownerFieldsDto.setTelephone(telephone);
231	        String email = normalizeEmail(ownerFieldsDto.getEmail());
232	        ownerFieldsDto.setEmail(email);
233	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
234	        String postcode = ownerFieldsDto.getPostcode();
235	        // Deterministic household id: owners with the same normalized last name and postcode
236	        // share it automatically, regardless of creation order. It is no longer created by the
237	        // 'sharesHousehold' flag; that flag now only bypasses the duplicate block below.
238	        String householdId = householdId(lastName, postcode);
239	        // The household is keyed on (last name, postcode), so its existing members are the
240	        // existing owners with the same computed household id. Both the duplicate block and the
241	        // household size below key off this value.
242	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
243	            .filter(existing -> !existing.isDeleted())
244	            .filter(existing -> householdId.equals(
245	                householdId(normalizeHousehold(existing.getLastName()), existing.getPostcode())))
246	            .toList();
247	        // A second owner in an existing household is admitted as a household member; their
248	        // membership level is capped below (level-ceiling rule) rather than rejected.
249	        // Single, consolidated duplicate check: reject only when the new owner's whole derived
250	        // identity key (SHA-256 over telephone|email|soundex(lastName)) equals an existing,
251	        // non-deleted owner's. This single identity key is the only 409; there is no separate
252	        // household-duplicate rejection keyed off the computed householdId.
253	        String newLastName = ownerFieldsDto.getLastName();
254	        String identityKey = IdentityKeyDeriver.identityKey(telephone, email, newLastName);
255	        boolean identityInUse = this.clinicService.findAllOwners().stream()
256	            .filter(existing -> !existing.isDeleted())
257	            .anyMatch(existing -> identityKey.equals(IdentityKeyDeriver.identityKey(
258	                existing.getTelephone(), existing.getEmail(), existing.getLastName())));
259	        if (identityInUse) {
260	            throw new DuplicateIdentityException(
261	                "an owner with the same identity key already exists");
262	        }
263	        // Soft match: not a hard duplicate, but shares a household signature with an existing,
264	        // non-deleted owner — the same last-name Soundex and the same postcode while the identity
265	        // key differs (e.g. same last name and postcode but a different telephone). Such an owner
266	        // is still created (201) but flagged as a possible duplicate of the earliest matching owner
267	        // so it can be reviewed rather than rejected.
268	        String newSoundex = IdentityKeyDeriver.soundex(newLastName);
269	        Integer softMatchOf = this.clinicService.findAllOwners().stream()
270	            .filter(existing -> !existing.isDeleted())
271	            .filter(existing -> !identityKey.equals(IdentityKeyDeriver.identityKey(
272	                existing.getTelephone(), existing.getEmail(), existing.getLastName())))
273	            .filter(existing -> newSoundex.equals(IdentityKeyDeriver.soundex(existing.getLastName())))
274	            .filter(existing -> Objects.equals(postcode, existing.getPostcode()))
275	            .map(Owner::getId)
276	            .min(Integer::compareTo)
277	            .orElse(null);
278	        HttpHeaders headers = new HttpHeaders();
279	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
280	        owner.setRegistrationDate(registrationDate);
281	        owner.setCustomerCode(deduplicateCustomerCode(
282	            customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName())));
283	        owner.setHouseholdId(householdId);
284	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
285	        owner.setBulkSignupWarning(bulkSignupWarning);
286	        // Household size after this create: existing members plus the owner being created.
287	        owner.setHouseholdSize(householdMembers.size() + 1);
288	        // Level-ceiling: the new owner's membership level cannot exceed one above the current
