293	        int cappedLevel = naturalLevel;
294	        if (!householdMembers.isEmpty()) {
295	            int maxMemberLevel = householdMembers.stream()
296	                .mapToInt(MembershipPointsDeriver::effectiveMembershipLevel)
297	                .max()
298	                .orElseThrow();
299	            cappedLevel = Math.min(naturalLevel, maxMemberLevel + 1);
300	        }
301	        owner.setMembershipLevel(cappedLevel);
302	        // Flag a soft match (same last-name Soundex and postcode as an existing owner, but a
303	        // different identity key) as a possible duplicate of the earliest such owner; a create
304	        // with no soft match is left unflagged.
305	        owner.setPossibleDuplicate(softMatchOf != null);
306	        owner.setPossibleDuplicateOf(softMatchOf);
307	        owner.setDeleted(false);
308	        this.clinicService.saveOwner(owner);
309	        if (idempotencyKey != null) {
310	            idempotentCreates.put(idempotencyKey, owner.getId());
311	        }
312	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
313	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} "
314	            + "membershipNumber={}",
315	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
316	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
317	        emitOwnerCreatedEvent(owner, ownerDto);
318	        headers.setLocation(UriComponentsBuilder.newInstance()
319	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());

